export class UserHistory {
	time : string
	image : string
	text : string
	name : string
	englishName : string
	genus : string
	otherName : string
	constructor(time : string,
		image : string,
		text : string,
		name : string,
		englishName : string,
		genus : string,
		otherName : string) {
		this.time = time
		this.image = image
		this.text = text
		this.name = name
		this.englishName = englishName
		this.genus = genus
		this.otherName = otherName
	}
}